// Soạn tin báo lỗi gửi vào nhóm Zalo
const d = $input.first().json;
const wfName = (d.workflow && d.workflow.name) || 'không rõ';
const ex = d.execution || {};
const err = ex.error || (d.trigger && d.trigger.error) || {};
const node = ex.lastNodeExecuted || (err.node && err.node.name) || 'không rõ';
const msg = String(err.message || err.description || 'không rõ').replace(/\s+/g, ' ').slice(0, 300);
const now = DateTime.now().setZone('Asia/Ho_Chi_Minh').toFormat('dd/MM/yyyy HH:mm');
const text = `⚠️ HỆ THỐNG BÁO LỖI (${now})\nWorkflow: ${wfName}\nNode lỗi: ${node}\nLỗi: ${msg}`
  + (ex.id ? `\nLần chạy: #${ex.id}` : '')
  + `\n👉 Người phụ trách mở n8n → workflow trên → tab Executions để xem chi tiết.`;
return [{ json: { text } }];
